use vstd::prelude::*;

verus! {
    // Specification of membership in a slice
    spec fn in_array(a: &[i32], x: i32) -> bool
        reads a
    {
        // x is in a if there exists an index i with 0 ≤ i < a.len() and a[i] == x
        exists |i: nat| i < a.len() && a[i] == x
    }

    // Implementation of slice‐membership test
    fn is_in_array(a: &[i32], x: i32) -> bool
        ensures
            result == in_array(a, x),
    {
        let mut i: usize = 0;
        // We maintain that for all j < i, a[j] != x
        while i < a.len()
            invariant
                i <= a.len(),
                forall |j: nat| j < i ==> a[j] != x,
            decreases a.len() - i,
        {
            if a[i] == x {
                // Witness that indeed x appears at index i
                assert(in_array(a, x));
                return true;
            }
            i += 1;
        }
        // If we finish the loop, no index j < a.len() satisfies a[j] == x
        assert(forall |j: nat| j < a.len() ==> a[j] != x);
        assert(!in_array(a, x));
        false
    }

    // Membership in a Vec is just membership in its underlying slice
    fn contains(v: &Vec<i32>, x: i32) -> bool
        ensures
            result == in_array(v.as_slice(), x),
    {
        is_in_array(v.as_slice(), x)
    }

    // Remove from a all elements that also appear in b, and eliminate duplicates.
    fn remove_elements(a: &[i32], b: &[i32]) -> Vec<i32>
        ensures
            // Every element of the result comes from a and does NOT appear in b
            forall |k: nat| k < result.len() ==>
                in_array(a, result[k]) && !in_array(b, result[k]),
            // No duplicates in the result
            forall |i: nat, j: nat| i < j && j < result.len() ==>
                result[i] != result[j],
            // Completeness: every x in a but not in b appears in the result
            forall |x: i32| in_array(a, x) && !in_array(b, x) ==>
                exists |k: nat| k < result.len() && result[k] == x,
    {
        let mut res: Vec<i32> = Vec::new();
        let mut idx: usize = 0;
        // We process a[0..idx), and maintain:
        // 1) res contains exactly the distinct elements in a[0..idx) that are not in b
        // 2) no duplicates in res
        // 3) completeness up to idx
        while idx < a.len()
            invariant
                idx <= a.len(),
                forall |k: nat| k < res.len() ==>
                    in_array(a[0..idx], res[k]) && !in_array(b, res[k]),
                forall |i: nat, j: nat| i < j && j < res.len() ==>
                    res[i] != res[j],
                forall |x: i32| in_array(a[0..idx], x) && !in_array(b, x) ==>
                    exists |k: nat| k < res.len() && res[k] == x,
            decreases a.len() - idx,
        {
            let x = a[idx];
            // If x does not appear in b, and we haven't already pushed x, then push it
            if !is_in_array(b, x) {
                if !contains(&res, x) {
                    res.push(x);
                }
            }
            idx += 1;
        }
        res
    }
}

